import {canvasScenes} from './canvas-scenes.mjs';import {SpatialScenes} from './three-scenes.mjs';import {grain,text,caption,rect} from './drawing.mjs';
export function createRenderer(canvas){canvas.width=1280;canvas.height=720;const x=canvas.getContext('2d',{willReadFrequently:true});let spatial,device,devicePromise;
async function prepare(scene,props){if(scene!=='device')return;if(!device){devicePromise??=import(new URL('/runtime/device.mjs',window.location.origin).href).then(m=>device=new m.DeviceScene()).catch(e=>{devicePromise=null;throw e});await devicePromise;}await device.prepare(props);}

return {prepare,dispose(){device?.dispose();spatial?.renderer?.dispose?.()},draw(scene,time,props){canvas.width=1280;if(scene==='device'){x.drawImage(device.draw(time,props),0,0);text(x,'PRODUCT FILM / 012',68,65,12,'#586c67');text(x,props.brand.toUpperCase(),68,215,Math.min(56,480/Math.max(1,props.brand.length)*1.6),'#193c37','left','Arial');text(x,'Made for the',68,286,48,'#193c37','left','Georgia');text(x,'way you move.',68,342,48,'#193c37','left','Georgia');rect(x,70,386,64,5,props.accent,2);text(x,props.app==='Wallet'?'Your money. A clearer view.':props.app==='Analytics'?'Every signal. One simple view.':'A great idea starts here.',70,431,21,'#536964');text(x,'FICTIONAL APP · REAL 3D DEVICE',70,476,11,'#6d7c75');const beat=Math.min(2,Math.floor(time/5.34));text(x,['01 / A NEW PERSPECTIVE','02 / DESIGNED AROUND YOU','03 / READY FOR WHAT’S NEXT'][beat],70,609,12,'#193c37');rect(x,70,631,370,2,'#c5ccc2');rect(x,70,631,370*time/16,2,'#193c37');}else if(canvasScenes[scene])canvasScenes[scene](x,time,props);else{spatial??=new SpatialScenes();x.drawImage(spatial.draw(scene,time,props),0,0);const g=x.createLinearGradient(0,450,0,720);g.addColorStop(0,'#08121b00');g.addColorStop(1,'#08121bc9');rect(x,0,450,1280,270,g);const captions={dragon:['The fossil takes flight.','Articulated bones · a procedural creature study'],castle:['A kingdom in miniature.','Stone, water, wind · an original procedural diorama'],underwater:['The last blue train.','There is always another way home.']};caption(x,...captions[scene]);text(x,scene==='dragon'?'SPECIMEN / 014':scene==='castle'?'MINIATURE WORLDS / 002':'DEPTH / 021',63,59,12,'#f0e5cf');if(scene==='underwater'){x.save();x.globalAlpha=.12;for(let i=0;i<12;i++){x.strokeStyle='#c5f2e0';x.lineWidth=1.5;x.beginPath();for(let a=0;a<1280;a+=15)x[a?'lineTo':'moveTo'](a,70+i*57+Math.sin(a*.012+time*.7+i)*12);x.stroke()}x.restore();}grain(x,time,.055)}return canvas},canvas}}
// Optional adapter; the editor does not prescribe any scene language.
export function referenceAdapter(){let r;return {id:'reference',protocol:1,render:async({template,time,nodes})=>{if(!r)r=createRenderer(document.createElement('canvas'));return r.draw(template.scene,time,nodes.find(n=>!n.overlay).props)}}}
